  camera.position.set(0, 6.8, 30.5);
  camera.lookAt(0, 0.7, 0);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  container.insertBefore(renderer.domElement, overlayLayer);

  // --- Lighting ---
  const ambientLight = new THREE.AmbientLight(0xfff8eb, 1.35);
  scene.add(ambientLight);

  const dirLight = new THREE.DirectionalLight(0xfff4df, 1.5);
  dirLight.position.set(8, 18, 14);
  dirLight.castShadow = true;
  dirLight.shadow.mapSize.width = 2048;
  dirLight.shadow.mapSize.height = 2048;
  dirLight.shadow.camera.left = -18;
  dirLight.shadow.camera.right = 18;
  dirLight.shadow.camera.top = 10;
  dirLight.shadow.camera.bottom = -10;
  scene.add(dirLight);

  const fillLight = new THREE.DirectionalLight(0xe8dfc8, 0.6);
  fillLight.position.set(-10, 6, 10);
  scene.add(fillLight);

  // --- Shared Palette Materials ---
  const matPaperLight = new THREE.MeshStandardMaterial({ color: 0xede2cc, roughness: 0.85 });
  const matPaperMid = new THREE.MeshStandardMaterial({ color: 0xd9cbb0, roughness: 0.85 });
  const matPaperDark = new THREE.MeshStandardMaterial({ color: 0xb8a686, roughness: 0.85 });
  const matInk = new THREE.MeshStandardMaterial({ color: 0x26221d, roughness: 0.7 });

  const matVaultBlue = new THREE.MeshStandardMaterial({ color: 0x1d5bbf, roughness: 0.4, metalness: 0.25 });
  const matVaultBlueDark = new THREE.MeshStandardMaterial({ color: 0x123878, roughness: 0.45, metalness: 0.3 });
  const matVaultBlueAccent = new THREE.MeshStandardMaterial({
    color: 0x4299e1,
    emissive: 0x1a4971,
    emissiveIntensity: 0.35,
    roughness: 0.3
  });

  const matYellowMessage = new THREE.MeshStandardMaterial({
    color: 0xecc94b,
    emissive: 0x975a16,
    emissiveIntensity: 0.22,
    roughness: 0.35
  });

  const matRedMoney = new THREE.MeshStandardMaterial({
    color: 0xd93025,
    emissive: 0x63171b,
    emissiveIntensity: 0.25,
    roughness: 0.35,
    metalness: 0.2
  });
  const matRedChainLink = new THREE.MeshStandardMaterial({
    color: 0x9b2c2c,
    roughness: 0.45,
    metalness: 0.3
  });

  // --- Stage Floor / Plinth ---
  const stageGroup = new THREE.Group();
  scene.add(stageGroup);

  const plinthGeo = new THREE.BoxGeometry(30.5, 0.5, 6.4);
  const plinthMesh = new THREE.Mesh(plinthGeo, matPaperMid);
  plinthMesh.position.set(0, -0.95, 0);
  plinthMesh.receiveShadow = true;
  stageGroup.add(plinthMesh);

  const trimGeo = new THREE.BoxGeometry(30.7, 0.08, 6.55);
  const trimMesh = new THREE.Mesh(trimGeo, matInk);
  trimMesh.position.set(0, -0.7, 0);
  stageGroup.add(trimMesh);

  // Subtle track line connecting Agent -> Spend -> Vault
  const requestTrackGeo = new THREE.BoxGeometry(10.0, 0.04, 0.14);
  const requestTrackMesh = new THREE.Mesh(requestTrackGeo, matPaperDark);
  requestTrackMesh.position.set(-2.5, -0.67, 0);
  stageGroup.add(requestTrackMesh);

  // Station X Coordinates (left to right)
  const STATION_X = {
    buyer: -12.5,
    agent: -7.5,
    spend: -2.5,
    vault: 2.5,
    merchant: 7.5,
    chain: 12.5
  };

  // Create Station Pedestals
  Object.values(STATION_X).forEach((x) => {
    const padGeo = new THREE.CylinderGeometry(1.55, 1.65, 0.16, 32);
    const padMesh = new THREE.Mesh(padGeo, matPaperLight);
    padMesh.position.set(x, -0.62, 0);
    padMesh.receiveShadow = true;
    stageGroup.add(padMesh);

    const ringGeo = new THREE.TorusGeometry(1.58, 0.035, 12, 48);
    const ringMesh = new THREE.Mesh(ringGeo, matInk);
    ringMesh.rotation.x = Math.PI / 2;
    ringMesh.position.set(x, -0.54, 0);
    stageGroup.add(ringMesh);
  });

  // --- 1. BUYER COMPANY (x = -12.5): small building, paper tones ---
  const buyerGroup = new THREE.Group();
  buyerGroup.position.set(STATION_X.buyer, -0.54, 0);
  scene.add(buyerGroup);

  const buyerMain = new THREE.Mesh(new THREE.BoxGeometry(2.1, 2.2, 1.7), matPaperLight);
  buyerMain.position.set(0, 1.1, 0);
  buyerMain.castShadow = true;
  buyerMain.receiveShadow = true;
  buyerGroup.add(buyerMain);

  const buyerWing = new THREE.Mesh(new THREE.BoxGeometry(0.85, 1.5, 1.4), matPaperMid);
  buyerWing.position.set(-1.1, 0.75, -0.1);
  buyerWing.castShadow = true;
  buyerGroup.add(buyerWing);

  const buyerRoof = new THREE.Mesh(new THREE.ConeGeometry(1.65, 0.9, 4), matPaperDark);
  buyerRoof.position.set(0, 2.65, 0);
  buyerRoof.rotation.y = Math.PI / 4;
  buyerRoof.castShadow = true;
  buyerGroup.add(buyerRoof);

  // Windows & door in dark ink tones
  for (let row = 0; row < 2; row++) {
    for (let col = -1; col <= 1; col += 2) {
      const win = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.36, 0.06), matInk);
      win.position.set(col * 0.45, 1.15 + row * 0.6, 0.86);
      buyerGroup.add(win);
    }
  }
  const buyerDoor = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.68, 0.06), matInk);
  buyerDoor.position.set(0, 0.34, 0.86);
  buyerGroup.add(buyerDoor);

  // --- 2. GEMINI AGENT (x = -7.5): figure/terminal, paper tones with yellow message accents ---
  const agentGroup = new THREE.Group();
  agentGroup.position.set(STATION_X.agent, -0.54, 0);
  scene.add(agentGroup);

  const agentBase = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.2, 1.3), matPaperMid);
  agentBase.position.set(0, 0.6, 0);
  agentBase.castShadow = true;
  agentGroup.add(agentBase);

  const agentConsole = new THREE.Mesh(new THREE.BoxGeometry(1.55, 1.15, 0.95), matPaperLight);
  agentConsole.position.set(0, 1.65, 0);
  agentConsole.castShadow = true;
  agentGroup.add(agentConsole);

  const agentScreen = new THREE.Mesh(new THREE.BoxGeometry(1.25, 0.78, 0.06), matInk);
  agentScreen.position.set(0, 1.68, 0.48);
  agentGroup.add(agentScreen);

  // Yellow message accents on screen and antenna
  for (let i = 0; i < 3; i++) {
    const barWidth = i === 2 ? 0.65 : 0.95;
    const msgBar = new THREE.Mesh(new THREE.BoxGeometry(barWidth, 0.1, 0.04), matYellowMessage);
    msgBar.position.set((barWidth - 0.95) / 2, 1.86 - i * 0.2, 0.51);
    agentGroup.add(msgBar);
  }

  const antennaStem = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.55, 12), matInk);
  antennaStem.position.set(0, 2.5, 0);
  agentGroup.add(antennaStem);

  const antennaBeacon = new THREE.Mesh(new THREE.OctahedronGeometry(0.26, 0), matYellowMessage);
  antennaBeacon.position.set(0, 2.88, 0);
  agentGroup.add(antennaBeacon);

  // --- 3. SPEND POLICY (x = -2.5): gate or checkpoint ---
  const spendGroup = new THREE.Group();
  spendGroup.position.set(STATION_X.spend, -0.54, 0);
  scene.add(spendGroup);

  const pillarGeo = new THREE.BoxGeometry(0.42, 2.75, 0.52);
  const leftPillar = new THREE.Mesh(pillarGeo, matPaperMid);
  leftPillar.position.set(-0.9, 1.375, 0);
  leftPillar.castShadow = true;
  spendGroup.add(leftPillar);

  const rightPillar = new THREE.Mesh(pillarGeo, matPaperMid);
  rightPillar.position.set(0.9, 1.375, 0);
  rightPillar.castShadow = true;
  spendGroup.add(rightPillar);

  const archBeam = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.48, 0.64), matInk);
  archBeam.position.set(0, 2.85, 0);
  archBeam.castShadow = true;
  spendGroup.add(archBeam);

  // Checkpoint gate bar
  const gateBarMat = new THREE.MeshStandardMaterial({ color: 0xb8a686, roughness: 0.5 });
  const gateBar = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 1.5, 16), gateBarMat);
  gateBar.rotation.z = Math.PI / 2;
  gateBar.position.set(0, 1.35, 0.25);
  spendGroup.add(gateBar);

  const gateLampMat = new THREE.MeshStandardMaterial({
    color: 0xd69e2e,
    emissive: 0xd69e2e,
    emissiveIntensity: 0.15,
    roughness: 0.4
