  const gateLamp = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.18, 0.68), gateLampMat);
  gateLamp.position.set(0, 2.85, 0);
  spendGroup.add(gateLamp);

  // --- 4. BASIS THEORY VAULT (x = 2.5): blue vault box; key drawn inside and never leaves ---
  const vaultGroup = new THREE.Group();
  vaultGroup.position.set(STATION_X.vault, -0.54, 0);
  scene.add(vaultGroup);

  // Blue vault exterior walls forming a recessed front chamber so the key inside is always visible
  const vaultBack = new THREE.Mesh(new THREE.BoxGeometry(2.3, 2.5, 0.9), matVaultBlue);
  vaultBack.position.set(0, 1.25, -0.35);
  vaultBack.castShadow = true;
  vaultGroup.add(vaultBack);

  const vaultLeftWall = new THREE.Mesh(new THREE.BoxGeometry(0.38, 2.5, 0.8), matVaultBlue);
  vaultLeftWall.position.set(-0.96, 1.25, 0.45);
