      chainGroup.add(link);
    }
  });

  // Appended 4th block (part of static chain station, hidden until settled ledger cue at t=25000ms)
  const appendedBlockGroup = new THREE.Group();
  appendedBlockGroup.visible = false;
  chainGroup.add(appendedBlockGroup);

  const appendedLink = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.22, 12), matRedChainLink);
  appendedLink.rotation.z = Math.PI / 2;
  appendedLink.position.set(0.625, 0.85, 0);
  appendedBlockGroup.add(appendedLink);

  const appendedBlockMesh = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.5, 0.5), matRedMoney);
  appendedBlockMesh.position.set(0.95, 0.85, 0);
  appendedBlockMesh.castShadow = true;
  appendedBlockGroup.add(appendedBlockMesh);

  const ledgerPulseMat = new THREE.MeshBasicMaterial({
    color: 0xe53e3e,
    transparent: true,
    opacity: 0.0,
    side: THREE.DoubleSide
  });
  const ledgerPulseRing = new THREE.Mesh(new THREE.RingGeometry(0.32, 0.44, 32), ledgerPulseMat);
  ledgerPulseRing.position.set(0.95, 0.85, 0.3);
  appendedBlockGroup.add(ledgerPulseRing);

  // --- Dynamic Moving Objects ---
  function createPacketMesh() {
    const group = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.46, 0.42), matYellowMessage);
    body.castShadow = true;
    group.add(body);

    const band = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.1, 0.44), matInk);
    group.add(band);

    // Optional blue vault seal on packet (hidden until sealed by vault)
    const seal = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.48, 24), matVaultBlue);
    seal.rotation.x = Math.PI / 2;
    seal.visible = false;
    seal.name = 'vaultSeal';
    group.add(seal);

    group.visible = false;
    scene.add(group);
    return group;
  }

  const packetRefusedMesh = createPacketMesh();
  const packetSettledMesh = createPacketMesh();

  // Refusal mark at the vault: blue seal with a cross
  const refusalMarkGroup = new THREE.Group();
  refusalMarkGroup.position.set(STATION_X.vault - 0.85, 2.15, 0.92);
  refusalMarkGroup.visible = false;
  scene.add(refusalMarkGroup);

  const refusalDisc = new THREE.Mesh(new THREE.CylinderGeometry(0.46, 0.46, 0.12, 32), matVaultBlue);
  refusalDisc.rotation.x = Math.PI / 2;
  refusalMarkGroup.add(refusalDisc);

  const refusalRim = new THREE.Mesh(new THREE.TorusGeometry(0.46, 0.045, 12, 32), matVaultBlueAccent);
  refusalMarkGroup.add(refusalRim);

  const matCross = new THREE.MeshStandardMaterial({
    color: 0xfbf7ed,
    emissive: 0x90cdf4,
    emissiveIntensity: 0.35,
    roughness: 0.2
  });
  const crossBar1 = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.12, 0.08), matCross);
  crossBar1.rotation.z = Math.PI / 4;
  crossBar1.position.z = 0.07;
  refusalMarkGroup.add(crossBar1);

  const crossBar2 = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.12, 0.08), matCross);
  crossBar2.rotation.z = -Math.PI / 4;
  crossBar2.position.z = 0.07;
  refusalMarkGroup.add(crossBar2);

  // Red Coin for settled payment (moves Buyer -> Merchant)
  const coinGroup = new THREE.Group();
  coinGroup.visible = false;
  scene.add(coinGroup);

  const coinCylinder = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.16, 32), matRedMoney);
  coinCylinder.rotation.x = Math.PI / 2;
  coinCylinder.castShadow = true;
  coinGroup.add(coinCylinder);

  const coinRim = new THREE.Mesh(
    new THREE.TorusGeometry(0.48, 0.045, 12, 32),
    new THREE.MeshStandardMaterial({ color: 0xfefcbf, roughness: 0.3, metalness: 0.4 })
  );
  coinGroup.add(coinRim);

  // --- HTML Overlay Labels ---
  function createOverlayDiv(className, htmlContent) {
    const div = document.createElement('div');
    div.className = className;
    div.innerHTML = htmlContent;
    overlayLayer.appendChild(div);
    return div;
  }

  const stationLabelDefs = [
    { text: 'Buyer company', pos: new THREE.Vector3(STATION_X.buyer, -1.25, 1.7) },
    { text: 'Gemini agent', pos: new THREE.Vector3(STATION_X.agent, -1.25, 1.7) },
    { text: 'Spend policy', pos: new THREE.Vector3(STATION_X.spend, -1.25, 1.7) },
    { text: 'Basis Theory vault', pos: new THREE.Vector3(STATION_X.vault, -1.25, 1.7) },
    { text: 'Merchant', pos: new THREE.Vector3(STATION_X.merchant, -1.25, 1.7) },
    { text: 'Base Sepolia chain', pos: new THREE.Vector3(STATION_X.chain, -1.25, 1.7) }
  ];

  const stationLabelDom = stationLabelDefs.map((def) => ({
    el: createOverlayDiv('station-label', def.text),
    pos: def.pos
  }));

  const packetRefusedLabelEl = createOverlayDiv('dynamic-label label-packet', '');
  packetRefusedLabelEl.style.display = 'none';

  const refusalBadgeLabelEl = createOverlayDiv('dynamic-label label-refusal', '');
  refusalBadgeLabelEl.style.display = 'none';

  const packetSettledLabelEl = createOverlayDiv('dynamic-label label-packet', '');
  packetSettledLabelEl.style.display = 'none';

  const coinLabelEl = createOverlayDiv('dynamic-label label-coin', '');
  coinLabelEl.style.display = 'none';

  const ledgerLabelEl = createOverlayDiv('dynamic-label label-ledger', '');
  ledgerLabelEl.style.display = 'none';

  function projectToScreen(vec3, domEl) {
    const v = vec3.clone().project(camera);
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
    domEl.style.left = `${x.toFixed(1)}px`;
    domEl.style.top = `${y.toFixed(1)}px`;
  }

  function setCaption(mainSentence, orderId, tMs) {
    const fullText = `${mainSentence} ${orderId}`;
    captionBar.innerHTML = `<span>${mainSentence} <span class="caption-order-id">${orderId}</span></span>`;
    captionBar.style.opacity = '1';
    internal.recordLabel(fullText, tMs, orderId);
  }

  // --- Timeline Beats & State Flags ---
  // Beat 1 (Event 0: refused, ord_429bfdbc-7c9c-4fbe-90be-9323b2b587fa):
  //   1000ms: packet appears at agent, travels agent -> spend -> vault
  //   6000ms: packet stops at vault; refusal seal + code "refused rule_payto" appear; caption updates
  //   12800ms: Beat 1 packet removed before Beat 2 begins
  // Beat 2 (Event 1: settled, ord_99b70e93-7b65-4edd-a97f-8464c86f2b0d):
  //   13500ms: packet appears at agent, travels agent -> spend -> vault
  //   18000ms - 19500ms: vault seals packet in blue
  //   19500ms: red coin appears at buyer, travels buyer -> merchant
  //   24000ms: red coin reaches merchant; merchant lights up; settled caption appears
  //   25000ms: chain appends red block with pulse + ledger cue label
  //   25000ms - 32500ms: final state hold
  //   32500ms: done = true

  const state = {
    ev0Started: false,
    ev0RefusedShown: false,
    ev0PacketEnded: false,
    ev1Started: false,
    ev1Sealed: false,
    ev1CoinStarted: false,
    ev1SettledShown: false,
    ev1LedgerShown: false
  };

  const receiptShort = evSettled.txHash.slice(0, 10);
  const packetRefusedName = `packet:${evRefused.orderId}`;
  const refusalElementName = `refusal:${evRefused.orderId}`;
  const packetSettledName = `packet:${evSettled.orderId}`;
  const coinElementName = `coin:${evSettled.orderId}`;

  function easeInOutCubic(x) {
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function clamp01(v) {
    return Math.max(0, Math.min(1, v));
  }

  function updateScene(elapsedMs) {
    // Subtle slow camera drift keeping all 6 stations solidly framed
    camera.position.x = Math.sin(elapsedMs * 0.00018) * 0.28;
    camera.position.y = 6.8 + Math.cos(elapsedMs * 0.00014) * 0.1;
    camera.lookAt(0, 0.7, 0);

    antennaBeacon.rotation.y = elapsedMs * 0.002;

    // --- BEAT 1: REFUSED ORDER ---
    if (elapsedMs >= 1000 && !state.ev0Started) {
      state.ev0Started = true;
      internal.recordMark(elapsedMs, evRefused.kind, evRefused.orderId, 'refusal');
      internal.recordElementStart(packetRefusedName, elapsedMs, evRefused.orderId);
      packetRefusedMesh.visible = true;

      const reqText = `asked ${evRefused.orderId}`;
      packetRefusedLabelEl.innerHTML = `asked<span class="order-sub">${evRefused.orderId}</span>`;
      packetRefusedLabelEl.style.display = 'block';
      internal.recordLabel(reqText, elapsedMs, evRefused.orderId);
    }

    if (state.ev0Started && !state.ev0PacketEnded) {
      let px = STATION_X.agent;
      let py = 1.45;
      if (elapsedMs < 3200) {
        const p = easeInOutCubic(clamp01((elapsedMs - 1000) / 2200));
        px = STATION_X.agent + (STATION_X.spend - STATION_X.agent) * p;
        py = 1.45 + Math.sin(p * Math.PI) * 0.45;
      } else if (elapsedMs < 3800) {
        px = STATION_X.spend;
        py = 1.45;
        gateLampMat.emissiveIntensity = 0.85;
      } else if (elapsedMs < 6000) {
        gateLampMat.emissiveIntensity = 0.2;
        const p = easeInOutCubic(clamp01((elapsedMs - 3800) / 2200));
        px = STATION_X.spend + (STATION_X.vault - 1.05 - STATION_X.spend) * p;
        py = 1.45 + Math.sin(p * Math.PI) * 0.45;
      } else {
        px = STATION_X.vault - 1.05;
        py = 1.35;
      }
      packetRefusedMesh.position.set(px, py, 0.9);
      projectToScreen(new THREE.Vector3(px, py + 0.85, 0.9), packetRefusedLabelEl);
    }

    if (elapsedMs >= 6000 && !state.ev0RefusedShown) {
      state.ev0RefusedShown = true;
      packetRefusedLabelEl.style.display = 'none';

      refusalMarkGroup.visible = true;
      internal.recordElementStart(refusalElementName, elapsedMs, evRefused.orderId);

      const refusalBadgeText = `refused ${evRefused.code} ${evRefused.orderId}`;
      refusalBadgeLabelEl.innerHTML = `refused ${evRefused.code}<span class="order-sub">${evRefused.orderId}</span>`;
      refusalBadgeLabelEl.style.display = 'block';
      internal.recordLabel(refusalBadgeText, elapsedMs, evRefused.orderId);

      setCaption(`Vault refused the payment: ${evRefused.code}`, evRefused.orderId, elapsedMs);
    }

    if (state.ev0RefusedShown) {
      projectToScreen(
        new THREE.Vector3(STATION_X.vault - 0.2, 3.05, 0.6),
        refusalBadgeLabelEl
      );
    }

    if (elapsedMs >= 12800 && !state.ev0PacketEnded) {
      state.ev0PacketEnded = true;
      packetRefusedMesh.visible = false;
      internal.recordElementEnd(packetRefusedName, elapsedMs);
    }

    // --- BEAT 2: SETTLED ORDER ---
    if (elapsedMs >= 13500 && !state.ev1Started) {
      state.ev1Started = true;
      internal.recordMark(elapsedMs, evSettled.kind, evSettled.orderId, 'coin');
      internal.recordElementStart(packetSettledName, elapsedMs, evSettled.orderId);
      packetSettledMesh.visible = true;

      const reqText2 = `asked ${evSettled.amount} USDC ${evSettled.orderId}`;
      packetSettledLabelEl.innerHTML = `asked ${evSettled.amount} USDC<span class="order-sub">${evSettled.orderId}</span>`;
      packetSettledLabelEl.style.display = 'block';
      internal.recordLabel(reqText2, elapsedMs, evSettled.orderId);
    }

    if (state.ev1Started) {
      let px = STATION_X.agent;
      let py = 1.45;
      if (elapsedMs < 15500) {
        const p = easeInOutCubic(clamp01((elapsedMs - 13500) / 2000));
        px = STATION_X.agent + (STATION_X.spend - STATION_X.agent) * p;
        py = 1.45 + Math.sin(p * Math.PI) * 0.45;
      } else if (elapsedMs < 16000) {
        px = STATION_X.spend;
        py = 1.45;
        gateLampMat.emissiveIntensity = 0.85;
      } else if (elapsedMs < 18000) {
        gateLampMat.emissiveIntensity = 0.2;
        const p = easeInOutCubic(clamp01((elapsedMs - 16000) / 2000));
        px = STATION_X.spend + (STATION_X.vault + 0.55 - STATION_X.spend) * p;
        py = 1.45 + Math.sin(p * Math.PI) * 0.45;
      } else {
        px = STATION_X.vault + 0.55;
        py = 1.35;
      }
      packetSettledMesh.position.set(px, py, 0.9);
      if (packetSettledLabelEl.style.display !== 'none') {
        projectToScreen(new THREE.Vector3(px, py + 0.85, 0.9), packetSettledLabelEl);
      }
    }

    // Vault seals the packet in blue at 18000ms (key stays strictly inside the vault)
    if (elapsedMs >= 18000 && !state.ev1Sealed) {
      state.ev1Sealed = true;
      const sealMesh = packetSettledMesh.getObjectByName('vaultSeal');
      if (sealMesh) sealMesh.visible = true;
      matVaultKey.emissiveIntensity = 1.1;
    }

    // Only after the packet travels agent -> spend -> vault and is sealed in blue,
    // the red coin moves from Buyer company to Merchant (19500ms -> 24000ms)
    if (elapsedMs >= 19500 && !state.ev1CoinStarted) {
      state.ev1CoinStarted = true;
      packetSettledLabelEl.style.display = 'none';
      matVaultKey.emissiveIntensity = 0.55;

      coinGroup.visible = true;
      internal.recordElementStart(coinElementName, elapsedMs, evSettled.orderId);

      const coinText = `${evSettled.amount} USDC ${receiptShort} ${evSettled.orderId}`;
      coinLabelEl.innerHTML = `${evSettled.amount} USDC &middot; ${receiptShort}<span class="order-sub">${evSettled.orderId}</span>`;
      coinLabelEl.style.display = 'block';
      internal.recordLabel(coinText, elapsedMs, evSettled.orderId);
    }

    if (state.ev1CoinStarted) {
      const p = easeInOutCubic(clamp01((elapsedMs - 19500) / 4500));
      const cx = STATION_X.buyer + (STATION_X.merchant - STATION_X.buyer) * p;
      const cy = 1.35 + Math.sin(p * Math.PI) * 1.45;
      const cz = 1.35 + Math.sin(p * Math.PI) * 0.4;
      coinGroup.position.set(cx, cy, cz);
      coinGroup.rotation.y = p * Math.PI * 4;
      projectToScreen(new THREE.Vector3(cx, cy + 0.95, cz), coinLabelEl);
    }

    // Coin arrives at Merchant at 24000ms -> Merchant lights up & Settled caption appears
    if (elapsedMs >= 24000 && !state.ev1SettledShown) {
      state.ev1SettledShown = true;
      matMerchantBody.color.setHex(0xf2e5cc);
      matMerchantRoof.color.setHex(0x8c2d19);
      matMerchantAwning.color.setHex(0xc53030);
      matMerchantWindow.color.setHex(0xfefcbf);
      matMerchantWindow.emissive.setHex(0xf6ad55);
      matMerchantWindow.emissiveIntensity = 0.85;
      merchantGlowLight.intensity = 2.2;

      setCaption(
        `Settled on Base Sepolia: ${evSettled.amount} USDC, receipt ${receiptShort}`,
        evSettled.orderId,
        elapsedMs
      );
    }

    // Separate ledger cue at Base Sepolia chain at 25000ms (after coin's time)
    if (elapsedMs >= 25000 && !state.ev1LedgerShown) {
      state.ev1LedgerShown = true;
      appendedBlockGroup.visible = true;

      const ledgerCueText = `${evSettled.orderId} recorded on the ledger ${receiptShort}`;
      ledgerLabelEl.innerHTML = `recorded on the ledger ${receiptShort}<span class="order-sub">${evSettled.orderId}</span>`;
      ledgerLabelEl.style.display = 'block';
      internal.recordLabel(ledgerCueText, elapsedMs, evSettled.orderId);
    }

    if (state.ev1LedgerShown) {
      const pulseElapsed = elapsedMs - 25000;
      if (pulseElapsed < 2400) {
        const u = (pulseElapsed % 1200) / 1200;
        const scale = 1 + u * 2.2;
        ledgerPulseRing.scale.set(scale, scale, 1);
        ledgerPulseMat.opacity = (1 - u) * 0.85;
      } else {
        ledgerPulseMat.opacity = 0;
      }
      projectToScreen(
        new THREE.Vector3(STATION_X.chain + 0.1, 2.35, 0.5),
        ledgerLabelEl
      );
    }

    // Update static station label positions
    for (let i = 0; i < stationLabelDom.length; i++) {
      projectToScreen(stationLabelDom[i].pos, stationLabelDom[i].el);
    }

    renderer.render(scene, camera);

    // End with a 3 to 5 second hold of the final state, then set done = true
    if (elapsedMs >= 32500 && !window.__theater.done) {
      window.__theater.done = true;
    }
  }

  function tick() {
    const elapsedMs = performance.now() - internal.startTime;
    updateScene(elapsedMs);
    if (!window.__theater.done) {
      requestAnimationFrame(tick);
    }
  }

  // Backup interval so playback and marks advance reliably even if rAF is throttled
  const backupInterval = setInterval(() => {
    const elapsedMs = performance.now() - internal.startTime;
    updateScene(elapsedMs);
    if (window.__theater.done) {
      clearInterval(backupInterval);
    }
  }, 100);

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  requestAnimationFrame(tick);
</script>
